// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.system.handlerimport timber.log.Timberimport com.roshan.persona.brain.skill.SystemOperationimport com.roshan.persona.common.AppErrorimport com.roshan.persona.common.CorrelationIdimport com.roshan.persona.common.Resultimport com.roshan.persona.system.executor.ResourceCategoryimport com.roshan.persona.system.util.HardwareExceptionMapper/** * NOUS — Brightness Handler (Module 10 v2 — Step 10.4). * * Sets the screen brightness. Implements the full v2 handler contract: * idempotent execution, pre-state capture (brightness + auto-brightness), * exception mapping for `WRITE_SETTINGS` permission failures. * * ## Behavior * *  - **[isAvailable]**: always true (all devices have a screen). * *  - **[execute]**: *    1. Capture pre-state (previous brightness + auto-brightness mode). *    2. If auto-brightness is on, disable it (otherwise the system would *       override the user's explicit choice). *    3. Write the new brightness to `Settings.System.SCREEN_BRIGHTNESS` *       (persisted across reboots, 0-255 scale). *    4. Apply the brightness to the current window immediately *       (`WindowManager.LayoutParams.screenBrightness`, 0.0-1.0 scale). * *  - **[isAlreadyInTargetState]**: returns true if the current brightness *    matches the target (after normalizing both to the 0-1.0 scale). * *  - **[capturePreState]**: returns `BrightnessPreState(previousLevel, wasAuto)` *    so undo can restore BOTH the brightness AND the auto-brightness mode. * *  - **[restorePreState]**: restores the previous brightness + auto-brightness *    mode (re-enables auto-brightness if it was on before). * * ## Permission * * Requires `WRITE_SETTINGS` permission. Without it, `Settings.System.putInt` * throws `SecurityException` — mapped to * `Permission.SpecialAccessRequired` pointing to * `Settings.ACTION_MANAGE_WRITE_SETTINGS`. * * ## Resource category * * Brightness uses [ResourceCategory.DISPLAY] — multiple display operations * in a batch run **sequentially** to avoid Settings.System write contention. * * @see <a href="docs/strategy/module-10-system-strategy-v2.md">§Architecture — Handler Interface Upgrade</a> */class BrightnessHandler(    private val displayService: DisplayService,) : ReversibleHandler<SystemOperation.SetDisplayBrightness> {    override val id: String = "brightness"    override val displayName: String = "Display Brightness Control"    override val requiredPermissions: Set<String> = setOf(android.Manifest.permission.WRITE_SETTINGS)    override val resourceCategory: ResourceCategory = ResourceCategory.DISPLAY    override fun isAvailable(): Boolean = true  // all devices have a screen    override suspend fun execute(operation: SystemOperation.SetDisplayBrightness): Result<Unit> =        HardwareExceptionMapper.withMappingSync("brightness") {            try {                // 1. Disable auto-brightness so the system doesn't override our value.                if (displayService.isAutoBrightness()) {                    displayService.setAutoBrightness(false)                }                // 2. Convert 0.0-1.0 → 0-255 for persisted storage.                val level255 = (operation.level * MAX_BRIGHTNESS_255).toInt()                    .coerceIn(0, MAX_BRIGHTNESS_255)                displayService.setBrightness(level255)                // 3. Apply to current window immediately (0.0-1.0 scale).                displayService.applyWindowBrightness(operation.level)                Result.Success(Unit, CorrelationId.generate(), 0)            } catch (e: SecurityException) {                Result.Failure(                    error = AppError.Permission.SpecialAccessRequired(                        settingsIntent = android.provider.Settings.ACTION_MANAGE_WRITE_SETTINGS,                    ),                    correlationId = CorrelationId.generate(),                    durationNanos = 0,                )            }        }    override suspend fun capturePreState(operation: SystemOperation.SetDisplayBrightness): Any? {        return try {            val previousLevel255 = displayService.getBrightness()            val wasAuto = displayService.isAutoBrightness()            BrightnessPreState(                previousLevel255 = previousLevel255,                wasAuto = wasAuto,            )        } catch (t: Throwable) {            Timber.tag("BrightnessHandler").w("Failed to capture pre-state", t)            null        }    }    override suspend fun restorePreState(operation: SystemOperation.SetDisplayBrightness, preState: Any?) {        if (preState !is BrightnessPreState) return        try {            // Restore brightness first.            displayService.setBrightness(preState.previousLevel255)            // Restore auto-brightness mode (re-enable if it was on).            if (displayService.isAutoBrightness() != preState.wasAuto) {                displayService.setAutoBrightness(preState.wasAuto)            }            // Restore window brightness — if auto was on, use system default (null).            if (preState.wasAuto) {                displayService.applyWindowBrightness(null)            } else {                val level01 = preState.previousLevel255.toFloat() / MAX_BRIGHTNESS_255                displayService.applyWindowBrightness(level01)            }        } catch (t: Throwable) {            Timber.tag("BrightnessHandler").w("Failed to restore pre-state", t)        }    }    override suspend fun getCurrentState(): Any? {        return try {            BrightnessPreState(                previousLevel255 = displayService.getBrightness(),                wasAuto = displayService.isAutoBrightness(),            )        } catch (t: Throwable) { null }    }    override suspend fun isAlreadyInTargetState(operation: SystemOperation.SetDisplayBrightness): Boolean {        return try {            // If auto-brightness is on, the user's "set to 80%" would be overridden —            // not idempotent, we need to disable auto first.            if (displayService.isAutoBrightness()) return false            val current255 = displayService.getBrightness()            val current01 = current255.toFloat() / MAX_BRIGHTNESS_255            // Allow small tolerance (1/255) for float rounding.            return kotlin.math.abs(current01 - operation.level) < 0.005f        } catch (t: Throwable) {            false        }    }    override fun describeOperation(operation: SystemOperation.SetDisplayBrightness): String {        val percent = (operation.level * 100).toInt()        return "Brightness set to $percent%"    }    // ─── Pre-state serialization (audit defect B fix) ─────────────────────    override fun serializePreState(preState: Any?): String? {        if (preState == null) return null        if (preState !is BrightnessPreState) {            return com.roshan.persona.system.undo.SystemOperationSerializer.serializePreState(preState)        }        return "{\"type\":\"BrightnessPreState\"," +            "\"previousLevel255\":${preState.previousLevel255}," +            "\"wasAuto\":${preState.wasAuto}}"    }    override fun deserializePreState(json: String?): Any? {        if (json == null) return null        val map = try {            com.roshan.persona.system.undo.SystemOperationSerializer.parseJsonObject(json)        } catch (t: Throwable) {            return com.roshan.persona.system.undo.SystemOperationSerializer.deserializePreState(json)        }        return when (map["type"] as? String) {            "BrightnessPreState" -> BrightnessPreState(                previousLevel255 = (map["previousLevel255"] as? Number)?.toInt() ?: 128,                wasAuto = (map["wasAuto"] as? Boolean) ?: false,            )            else -> com.roshan.persona.system.undo.SystemOperationSerializer.deserializePreState(json)        }    }    /** Captured pre-state for brightness (previous level + auto mode). */    data class BrightnessPreState(        val previousLevel255: Int,        val wasAuto: Boolean,    )    private companion object {        private const val MAX_BRIGHTNESS_255 = 255    }}
